function i(t){return new Date(t).toLocaleDateString("en-US",{month:"short",day:"numeric"})}function c(t,e){return new Date(e).getTime()-new Date(t).getTime()}function s(t){const e=Date.now(),f=new Date(t).getTime(),r=Math.floor((e-f)/1e3);if(r<60)return"just now";const n=Math.floor(r/60);if(n<60)return`${n}m ago`;const o=Math.floor(n/60);if(o<24)return`${o}h ago`;const a=Math.floor(o/24);return a<7?`${a}d ago`:i(t)}export{s as r,c as s};
